// defaultStreamMaxLineBytes is the stdout scanner buffer size used when
// StreamConfig.MaxLineBytes is zero. 1 MiB comfortably fits the largest
// observed stream-json envelope lines without deadlocking on oversized ones.
const defaultStreamMaxLineBytes = 1 << 20

// StreamConfig configures a call to RunStreamingCLI. It captures the subprocess
// invocation plus the provider-specific fallback hooks so the runner can recover
// from older CLIs that reject streaming flags.
type StreamConfig struct {
	// Runner constructs the subprocess command. nil defaults to exec.CommandContext.
	Runner TextCommandRunner
	// Binary is the CLI binary name (passed to Runner).
	Binary string
	// DisplayName is the human-facing label used in error messages.
	DisplayName string
	// ProviderLabel is stamped onto every GenerationProgress emitted to progress.
	ProviderLabel string
	// Args are the CLI arguments (excluding the binary).
	Args []string
	// Stdin is piped to the subprocess. Empty means no stdin.
	Stdin string
	// LegacyFallback is invoked when the CLI rejects streaming flags (see
	// FallbackDetect). The returned text is returned as-is with no progress events.
	LegacyFallback func(ctx context.Context) (string, error)
	// FallbackDetect reports whether stderr indicates the CLI rejected the
	// streaming flags. When true and the subprocess failed, LegacyFallback runs.
	FallbackDetect func(stderr string) bool
	// MaxLineBytes sizes the stdout scanner buffer. 0 uses 1 MiB.
	MaxLineBytes int
}

// StreamState carries handler-owned scratch state across line invocations. The
// runner initializes StartedAt; handlers own everything else.
type StreamState struct {
	StartedAt            time.Time
	OutputTokensEstimate int
	Custom               map[string]any
}

// StreamResult is the terminal outcome returned by a StreamLineHandler. Exactly
// one of Text or Err is populated; Text triggers a synthetic PhaseDone emission
// while Err returns as-is and outranks context cancellation.
type StreamResult struct {
	Text         string
	DurationMs   int
	OutputTokens int
	Err          error
}

// StreamLineHandler processes one scanner line. It returns any progress events
// to forward, a non-nil *StreamResult to terminate the stream, and/or an error
// to abort immediately. Handlers must not block.
type StreamLineHandler func(line []byte, state *StreamState) (events []GenerationProgress, done *StreamResult, err error)

