// heartbeatStderrBufferBytes caps the stderr we retain for error reporting when
// a heartbeat subprocess fails. 10 KiB is enough for typical CLI banners and
// error traces without letting a chatty CLI balloon memory on a hang.
const heartbeatStderrBufferBytes = 10 * 1024

// heartbeatMaxLineRunes is the rune threshold above which forwarded stderr
