18	// GenerateTextStreaming runs the Claude CLI in stream-json mode, dispatches
19	// progress events to the optional callback, and returns the final result text.
20	// Implements the agent.StreamingTextGenerator interface.
21	//
22	// If the CLI rejects the stream-json flags (older Claude CLI), this falls back
23	// to the non-streaming GenerateText path — without progress events.
24	func (c *ClaudeCodeAgent) GenerateTextStreaming(
25		ctx context.Context,
26		prompt, model string,
27		progress agent.ProgressFn,
28	) (string, error) {
29		if model == "" {
30			model = "haiku"
31		}
32	
33		commandRunner := c.CommandRunner
34		if commandRunner == nil {
35			commandRunner = exec.CommandContext
36		}
37	
38		cmd := commandRunner(ctx, "claude",
39			"--print",
40			"--output-format", "stream-json",
41			"--verbose",
42			"--model", model,
43			"--setting-sources", "")
44	
45		cmd.Dir = os.TempDir()
46		cmd.Env = agent.StripGitEnv(os.Environ())
47		cmd.Stdin = strings.NewReader(prompt)
48	
49		stdout, err := cmd.StdoutPipe()
50		if err != nil {
51			return "", fmt.Errorf("claude stream stdout pipe: %w", err)
52		}
53		var stderr bytes.Buffer
54		cmd.Stderr = &stderr
55	
56		if err := cmd.Start(); err != nil {
57			return "", fmt.Errorf("claude stream start: %w", err)
58		}
59	
60		final, malformed, parseErr := streamClaudeResponse(stdout, makeProgressDispatcher(progress))
61		// Drain any unread stdout so the subprocess can exit cleanly even if the
62		// scanner aborted early (e.g. bufio.ErrTooLong on an oversized line).
63		// Without this, a blocked pipe would deadlock cmd.Wait() in interactive
64		// mode, which has no deadline. The copy error is intentionally discarded —
65		// stdout is about to be closed anyway.
66		if _, drainErr := io.Copy(io.Discard, stdout); drainErr != nil {
67			logging.Debug(ctx, "draining claude stream stdout", slog.String("error", drainErr.Error()))
68		}
69		waitErr := cmd.Wait()
70	
71		if malformed > 0 {
72			logging.Warn(ctx, "skipped malformed claude stream lines",
73				slog.Int("count", malformed))
74		}
75	
76		// A specific envelope error outranks a generic ctx-cancel message: if
77		// the stream produced an is_error result just before cancellation, the
78		// user deserves the specific cause (auth, rate-limit, etc.) rather than
79		// "canceled".
80		if final != nil && final.IsError {
81			return "", envelopeErrorMessage(final)
82		}
83	
84		// Context errors pass through as sentinels so callers can use errors.Is.
85		if ctx.Err() != nil {
86			if errors.Is(ctx.Err(), context.DeadlineExceeded) {
87				return "", context.DeadlineExceeded
88			}
89			return "", context.Canceled
90		}
91	
92		if final != nil {
93			if final.Result == nil {
94				return "", errors.New("claude returned empty result")
95			}
96			if progress != nil {
97				progress(agent.GenerationProgress{
98					Phase:        agent.PhaseDone,
99					OutputTokens: outputTokensFromUsage(final.Usage),
100					DurationMs:   final.DurationMs,
101				})
102			}
103			return *final.Result, nil
104		}
105	
106		// No envelope: check if the CLI rejected streaming flags (older version).
107		// If so, fall back to the non-streaming path.
108		if waitErr != nil {
109			stderrStr := stderr.String()
110			if looksLikeUnrecognizedFlag(stderrStr) {
111				logging.Warn(ctx, "claude CLI rejected stream-json flags; falling back to non-streaming (no progress output)",
112					slog.String("stderr", strings.TrimSpace(stderrStr)))
113				return c.GenerateText(ctx, prompt, model)
114			}
115			if stderrStr != "" {
116				return "", fmt.Errorf("claude stream failed: %s: %w", strings.TrimSpace(stderrStr), waitErr)
117			}
118			return "", fmt.Errorf("claude stream failed: %w", waitErr)
119		}
120	
121		if parseErr != nil {
122			return "", fmt.Errorf("claude stream parse: %w", parseErr)
123		}
124		return "", errors.New("claude exited without producing a result")
125	}
126	
127	// envelopeErrorMessage formats an is_error result envelope as a user-facing
128	// error. Preserves the CLI's result text and HTTP status when present.
129	func envelopeErrorMessage(final *streamEvent) error {
130		msg := "claude CLI reported error"
131		if final.Result != nil && *final.Result != "" {
132			msg = fmt.Sprintf("%s: %s", msg, *final.Result)
133		}
134		if final.APIErrorStatus != nil {
135			msg = fmt.Sprintf("%s (HTTP %d)", msg, *final.APIErrorStatus)
136		}
137		return errors.New(msg)
138	}
139	
140	// makeProgressDispatcher returns a per-event handler that translates raw
141	// stream events into agent.GenerationProgress callbacks. PhaseDone is
142	// emitted by GenerateTextStreaming after cmd.Wait, because it needs data
143	// from the parsed final envelope (OutputTokens, DurationMs).
144	func makeProgressDispatcher(progress agent.ProgressFn) func(streamEvent) {
145		if progress == nil {
146			return func(streamEvent) {} // progress disabled; scanner itself reads the stream
147		}
148		var outputTokensEstimate int
149		return func(ev streamEvent) {
150			switch {
151			case ev.Type == "system" && ev.Subtype == "status" && ev.Status == "requesting":
152				progress(agent.GenerationProgress{Phase: agent.PhaseConnecting})
153			case ev.Type == "stream_event" && ev.Event.Type == "message_start":
154				p := agent.GenerationProgress{Phase: agent.PhaseFirstToken, TTFTms: ev.TTFTms}
155				if ev.Event.Message != nil && ev.Event.Message.Usage != nil {
156					p.InputTokens = ev.Event.Message.Usage.InputTokens
157					p.CachedInputTokens = ev.Event.Message.Usage.CacheReadInputTokens
158				}
159				progress(p)
160			case ev.Type == "stream_event" && ev.Event.Type == "content_block_delta" && ev.Event.Delta != nil:
161				text := ev.Event.Delta.Text
162				if text == "" {
163					text = ev.Event.Delta.Thinking
164				}
165				outputTokensEstimate += len(text) / 4 // rough estimate: ~4 chars/token
166				progress(agent.GenerationProgress{Phase: agent.PhaseGenerating, OutputTokens: outputTokensEstimate})
167			}
168		}
169	}
170	
171	func outputTokensFromUsage(u *messageUsage) int {
172		if u == nil {
173			return 0
174		}
175		return u.OutputTokens
176	}
177	
178	// looksLikeUnrecognizedFlag returns true if stderr indicates the CLI
179	// rejected one of the streaming-specific flags (older Claude CLI that
180	// doesn't support stream-json or --verbose). Requires both a rejection
181	// phrase AND a streaming flag name to avoid false-positives on unrelated
182	// errors that happen to contain "unknown option".
183	func looksLikeUnrecognizedFlag(stderr string) bool {
184		lower := strings.ToLower(stderr)
185		hasRejectPhrase := strings.Contains(lower, "unrecognized option") ||
186			strings.Contains(lower, "unknown flag") ||
187			strings.Contains(lower, "unknown option") ||
188			strings.Contains(lower, "invalid option")
189		if !hasRejectPhrase {
190			return false
191		}
192		return strings.Contains(lower, "stream-json") ||
193			strings.Contains(lower, "verbose") ||
194			strings.Contains(lower, "include-partial")
195	}
