3	import (
4		"bufio"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9	)
10	
11	type responseEnvelope struct {
12		Type           string  `json:"type"`
13		Subtype        string  `json:"subtype"`
14		IsError        bool    `json:"is_error"`
15		APIErrorStatus *int    `json:"api_error_status"`
16		Result         *string `json:"result"`
17	}
18	
19	// parseGenerateTextResponse extracts the raw text payload and envelope metadata
20	// from Claude CLI JSON output. Claude may return either a single object or an array of events.
21	// The returned envelope allows callers to check IsError and APIErrorStatus.
22	func parseGenerateTextResponse(stdout []byte) (string, *responseEnvelope, error) {
23		var response responseEnvelope
24		if err := json.Unmarshal(stdout, &response); err == nil {
25			if response.Result != nil {
26				return *response.Result, &response, nil
27			}
28			// is_error:true with null result is a structured CLI failure; callers
29			// need the envelope (IsError, APIErrorStatus) for classification.
30			if response.IsError {
31				return "", &response, nil
32			}
33		}
34	
35		var responses []responseEnvelope
36		if err := json.Unmarshal(stdout, &responses); err != nil {
37			return "", nil, fmt.Errorf("unsupported Claude CLI JSON response: %w", err)
38		}
39	
40		for i := len(responses) - 1; i >= 0; i-- {
41			if responses[i].Type != "result" {
42				continue
43			}
44			if responses[i].Result != nil {
45				return *responses[i].Result, &responses[i], nil
46			}
47			// Mirror the object-path behavior: is_error:true with null result is
48			// a structured failure whose envelope (IsError, APIErrorStatus) must
49			// reach classifyEnvelopeError.
50			if responses[i].IsError {
51				return "", &responses[i], nil
52			}
53		}
54	
55		return "", nil, errors.New("unsupported Claude CLI JSON response: missing result item")
56	}
57	
58	// streamBufferMax bounds a single NDJSON line. Stream events can be large
59	// (init carries the full tool list; deltas can carry long thinking chunks)
60	// so we lift the default scanner limit substantially.
61	const streamBufferMax = 4 * 1024 * 1024 // 4 MiB
62	
63	// streamEvent represents one decoded line from the stream-json NDJSON output.
64	// Fields are populated based on the event Type/Subtype.
65	type streamEvent struct {
66		Type    string           `json:"type"`
67		Subtype string           `json:"subtype"`
68		Status  string           `json:"status"` // e.g. "requesting" for type=system,subtype=status
69		Event   streamInnerEvent `json:"event"`  // for type=stream_event
70	
71		// Fields populated for type=result.
72		IsError        bool          `json:"is_error"`
73		APIErrorStatus *int          `json:"api_error_status"`
74		Result         *string       `json:"result"`
75		DurationMs     int           `json:"duration_ms"`
76		TTFTms         int           `json:"ttft_ms,omitempty"` // time-to-first-token; on outer stream_event envelope
77		Usage          *messageUsage `json:"usage"`
78	}
79	
80	// streamInnerEvent holds the nested "event" payload for type=stream_event.
81	type streamInnerEvent struct {
82		Type    string         `json:"type"` // "message_start" | "content_block_delta" | "message_delta" | ...
83		Delta   *streamDelta   `json:"delta,omitempty"`
84		Message *streamMessage `json:"message,omitempty"`
85	}
86	
87	// streamDelta carries the content-block delta payload.
88	type streamDelta struct {
89		Type     string `json:"type"` // "text_delta" | "thinking_delta" | ...
90		Text     string `json:"text,omitempty"`
91		Thinking string `json:"thinking,omitempty"`
92	}
93	
94	// streamMessage is the partial-message payload on message_start. Only the
95	// usage field is currently consumed by callers; other fields are ignored.
96	type streamMessage struct {
97		Usage *messageUsage `json:"usage,omitempty"`
98	}
99	
100	// streamClaudeResponse reads NDJSON-encoded events from r, invokes onEvent
101	// for every successfully decoded event, and returns the final result event
102	// once the stream ends. Malformed lines are skipped to keep the stream
103	// resilient against single-line corruption; the count is returned so callers
104	// can log schema drift even on otherwise-successful runs.
105	func streamClaudeResponse(r io.Reader, onEvent func(streamEvent)) (*streamEvent, int, error) {
106		scanner := bufio.NewScanner(r)
107		scanner.Buffer(make([]byte, 64*1024), streamBufferMax)
108		var final *streamEvent
109		var malformedLines int
110		for scanner.Scan() {
111			line := scanner.Bytes()
112			if len(line) == 0 {
113				continue
114			}
115			var ev streamEvent
116			if err := json.Unmarshal(line, &ev); err != nil {
117				malformedLines++
118				continue // best-effort: skip and keep streaming
119			}
120			if onEvent != nil {
121				onEvent(ev)
122			}
123			if ev.Type == "result" {
124				captured := ev
125				final = &captured
126			}
127		}
128		if err := scanner.Err(); err != nil {
129			return nil, malformedLines, fmt.Errorf("reading claude stream: %w", err)
130		}
131		if final == nil {
132			if malformedLines > 0 {
133				return nil, malformedLines, fmt.Errorf("claude stream ended without a result event (%d malformed lines skipped)", malformedLines)
134			}
135			return nil, 0, errors.New("claude stream ended without a result event")
136		}
137		return final, malformedLines, nil
138	}
