44		}
45		if len(condensed) == 0 {
46			return nil, errors.New("transcript has no content to summarize")
47		}
48	
49		input := Input{
50			Transcript:   condensed,
51			FilesTouched: filesTouched,
52		}
53	
54		if generator == nil {
55			generator = &ClaudeGenerator{Progress: progress}
56		} else if cg, ok := generator.(*ClaudeGenerator); ok && cg.Progress == nil && progress != nil {
57			// Clone to avoid mutating the caller's struct.
58			clone := *cg
59			clone.Progress = progress
60			generator = &clone
61		}
62	
63		summary, err := generator.Generate(ctx, input)
64		if err != nil {
65			return nil, err //nolint:wrapcheck // preserve *ClaudeError for errors.As at the explain layer
66		}
67	
68		return summary, nil
69	}
