126	
127	// minimalDetailTools lists tools that should show only essential details in summaries.
128	// These tools often have verbose outputs that don't add value to summarization.
129	// The detail shown is typically just a path, URL, or identifier rather than full content.
130	var minimalDetailTools = map[string]bool{
131		"Skill":    true, // Show skill name only, not loaded content
132		"Read":     true, // Show file path only, not file contents
133		"WebFetch": true, // Show URL only, not fetched content
134	}
135	
136	// BuildCondensedTranscriptFromBytes parses pre-redacted transcript bytes and extracts a condensed view.
137	// This is a convenience function that combines parsing and condensing.
138	// The agentType parameter determines which parser to use (Claude/OpenCode JSONL vs Gemini JSON).
139	func BuildCondensedTranscriptFromBytes(content redact.RedactedBytes, agentType types.AgentType) ([]Entry, error) {
140		switch agentType {
141		case agent.AgentTypeGemini:
142			return buildCondensedTranscriptFromGemini(content)
143		case agent.AgentTypeFactoryAIDroid:
144			return buildCondensedTranscriptFromDroid(content)
145		case agent.AgentTypeOpenCode:
146			return buildCondensedTranscriptFromOpenCode(content)
147		case agent.AgentTypeCodex:
148			return buildCondensedTranscriptFromCodex(content)
149		case agent.AgentTypeClaudeCode, agent.AgentTypeCursor, agent.AgentTypeUnknown:
150			// Claude/cursor format - fall through to shared logic below
151		}
152		// Claude format (JSONL) - handles Claude Code, Unknown, and any future agent types
153		lines, err := transcript.ParseFromBytes(content.Bytes())
154		if err != nil {
155			return nil, fmt.Errorf("failed to parse transcript: %w", err)
156		}
157		return BuildCondensedTranscript(lines), nil
158	}
159	
160	// buildCondensedTranscriptFromGemini parses Gemini JSON transcript and extracts a condensed view.
161	func buildCondensedTranscriptFromGemini(redacted redact.RedactedBytes) ([]Entry, error) {
162		geminiTranscript, err := geminicli.ParseTranscript(redacted.Bytes())
163		if err != nil {
164			return nil, fmt.Errorf("failed to parse Gemini transcript: %w", err)
165		}
166	
167		var entries []Entry
168		for _, msg := range geminiTranscript.Messages {
169			switch msg.Type {
170			case geminicli.MessageTypeUser:
171				if msg.Content != "" {
172					entries = append(entries, Entry{
173						Type:    EntryTypeUser,
174						Content: msg.Content,
175					})
176				}
177			case geminicli.MessageTypeGemini:
178				// Add assistant content
179				if msg.Content != "" {
180					entries = append(entries, Entry{
181						Type:    EntryTypeAssistant,
182						Content: msg.Content,
183					})
184				}
185				// Add tool calls
186				for _, tc := range msg.ToolCalls {
187					entries = append(entries, Entry{
188						Type:       EntryTypeTool,
189						ToolName:   tc.Name,
190						ToolDetail: extractGenericToolDetail(tc.Args),
191					})
192				}
193			}
194		}
195	
196		return entries, nil
197	}
198	
199	// buildCondensedTranscriptFromOpenCode parses OpenCode export JSON transcript and extracts a condensed view.
200	func buildCondensedTranscriptFromOpenCode(redacted redact.RedactedBytes) ([]Entry, error) {
201		session, err := opencode.ParseExportSession(redacted.Bytes())
202		if err != nil {
203			return nil, fmt.Errorf("failed to parse OpenCode transcript: %w", err)
204		}
205		if session == nil {
206			return nil, nil
207		}
208	
209		var entries []Entry
210		for _, msg := range session.Messages {
211			switch msg.Info.Role {
212			case "user":
213				text := opencode.ExtractTextFromParts(msg.Parts)
214				if text != "" {
215					entries = append(entries, Entry{
216						Type:    EntryTypeUser,
217						Content: text,
218					})
219				}
220			case "assistant":
221				text := opencode.ExtractTextFromParts(msg.Parts)
222				if text != "" {
223					entries = append(entries, Entry{
224						Type:    EntryTypeAssistant,
225						Content: text,
226					})
227				}
228				for _, part := range msg.Parts {
229					if part.Type == "tool" && part.State != nil {
230						entries = append(entries, Entry{
231							Type:       EntryTypeTool,
232							ToolName:   part.Tool,
233							ToolDetail: extractOpenCodeToolDetail(part.State.Input),
234						})
235					}
236				}
237			}
238		}
239	
240		return entries, nil
241	}
242	
243	// buildCondensedTranscriptFromCodex converts Codex rollout JSONL into the compact
244	// transcript format, then reuses the shared transcript condensation logic.
245	func buildCondensedTranscriptFromCodex(content redact.RedactedBytes) ([]Entry, error) {
246		compacted, err := compact.Compact(content, compact.MetadataFields{
247			Agent:      "codex",
248			CLIVersion: "summarize",
249		})
250		if err != nil {
251			return nil, fmt.Errorf("failed to compact Codex transcript: %w", err)
252		}
253	
254		type compactUserTextBlock struct {
255			Text string `json:"text"`
256		}
257		type compactAssistantBlock struct {
258			Type  string          `json:"type"`
259			Text  string          `json:"text,omitempty"`
260			Name  string          `json:"name,omitempty"`
261			Input json.RawMessage `json:"input,omitempty"`
262		}
263		type compactLine struct {
264			Type    string          `json:"type"`
265			Content json.RawMessage `json:"content"`
266		}
267	
268		var entries []Entry
269		for _, lineBytes := range splitCompactJSONL(compacted) {
270			var line compactLine
271			if err := json.Unmarshal(lineBytes, &line); err != nil {
272				continue
273			}
274	
275			switch line.Type {
276			case transcript.TypeUser:
277				var blocks []compactUserTextBlock
278				if err := json.Unmarshal(line.Content, &blocks); err != nil {
279					continue
280				}
281				for _, block := range blocks {
282					if block.Text != "" {
283						entries = append(entries, Entry{
284							Type:    EntryTypeUser,
285							Content: block.Text,
286						})
287					}
288				}
289			case transcript.TypeAssistant:
290				var blocks []compactAssistantBlock
291				if err := json.Unmarshal(line.Content, &blocks); err != nil {
292					continue
293				}
294				for _, block := range blocks {
295					switch block.Type {
296					case transcript.ContentTypeText:
297						if block.Text != "" {
298							entries = append(entries, Entry{
299								Type:    EntryTypeAssistant,
300								Content: block.Text,
301							})
302						}
303					case transcript.ContentTypeToolUse:
304						var input map[string]interface{}
305						if err := json.Unmarshal(block.Input, &input); err != nil {
306							input = nil
307						}
308						entries = append(entries, Entry{
309							Type:       EntryTypeTool,
310							ToolName:   block.Name,
311							ToolDetail: extractGenericToolDetail(input),
312						})
313					}
314				}
315			}
316		}
317	
318		return entries, nil
319	}
320	
321	// buildCondensedTranscriptFromDroid parses Droid transcript and extracts a condensed view.
322	func buildCondensedTranscriptFromDroid(redacted redact.RedactedBytes) ([]Entry, error) {
323		droidLines, _, err := factoryaidroid.ParseDroidTranscriptFromBytes(redacted.Bytes(), 0)
324		if err != nil {
325			return nil, fmt.Errorf("failed to parse Droid transcript: %w", err)
326		}
327		return BuildCondensedTranscript(droidLines), nil
328	}
329	
330	// extractOpenCodeToolDetail extracts a detail string from an OpenCode tool's input map.
331	// OpenCode uses camelCase keys (e.g., "filePath" instead of "file_path").
332	func extractOpenCodeToolDetail(input map[string]interface{}) string {
333		for _, key := range []string{"description", "command", "filePath", "path", "pattern"} {
334			if v, ok := input[key].(string); ok && v != "" {
335				return v
336			}
337		}
338		return ""
339	}
340	
341	// extractGenericToolDetail extracts an appropriate detail string from a tool's input/args map.
342	// Checks common fields in order of preference.
343	func extractGenericToolDetail(input map[string]interface{}) string {
344		if input == nil {
345			return ""
346		}
347		for _, key := range []string{"description", "command", "cmd", "file_path", "path", "pattern"} {
348			if v, ok := input[key].(string); ok && v != "" {
349				return v
350			}
351		}
352		return ""
353	}
354	
355	func splitCompactJSONL(data []byte) [][]byte {
356		var lines [][]byte
357		for _, line := range bytes.Split(data, []byte("\n")) {
358			line = bytes.TrimSpace(line)
359			if len(line) > 0 {
360				lines = append(lines, line)
361			}
362		}
363		return lines
364	}
365	
366	// BuildCondensedTranscript extracts a condensed view of the transcript.
367	// It processes user prompts, assistant responses, and tool calls into
368	// a simplified format suitable for LLM summarization.
369	func BuildCondensedTranscript(lines []transcript.Line) []Entry {
370		var entries []Entry
371	
372		for _, line := range lines {
373			switch line.Type {
374			case transcript.TypeUser:
375				if entry := extractUserEntry(line); entry != nil {
376					entries = append(entries, *entry)
377				}
378			case transcript.TypeAssistant:
379				assistantEntries := extractAssistantEntries(line)
380				entries = append(entries, assistantEntries...)
381			}
382		}
383	
384		return entries
385	}
386	
387	// skillContentPrefix identifies user messages that are skill content injections.
388	// These are injected after a Skill tool call and contain the full skill instructions.
389	const skillContentPrefix = "Base directory for this skill:"
390	
391	// extractUserEntry extracts a user entry from a transcript line.
392	// Returns nil if the line doesn't contain a valid user prompt or is skill content.
393	func extractUserEntry(line transcript.Line) *Entry {
394		content := transcript.ExtractUserContent(line.Message)
395		if content == "" {
396			return nil
397		}
398	
399		// Skip skill content injections - these are verbose skill instructions
400		// injected as user messages after Skill tool invocations in Claude Code.
401		// The prefix "Base directory for this skill:" is added by the superpowers
402		// plugin when loading skill content. This filtering reduces transcript noise
403		// since skill content is documentation, not user intent.
404		if strings.HasPrefix(content, skillContentPrefix) {
405			return nil
406		}
407	
408		return &Entry{
409			Type:    EntryTypeUser,
410			Content: content,
411		}
412	}
413	
414	// extractAssistantEntries extracts assistant and tool entries from a transcript line.
415	func extractAssistantEntries(line transcript.Line) []Entry {
416		var msg transcript.AssistantMessage
417		if err := json.Unmarshal(line.Message, &msg); err != nil {
418			return nil
419		}
420	
421		var entries []Entry
422	
423		for _, block := range msg.Content {
424			switch block.Type {
425			case transcript.ContentTypeText:
426				if block.Text != "" {
427					entries = append(entries, Entry{
428						Type:    EntryTypeAssistant,
429						Content: block.Text,
430					})
431				}
432			case transcript.ContentTypeToolUse:
433				var input transcript.ToolInput
434				_ = json.Unmarshal(block.Input, &input) //nolint:errcheck // Best-effort parsing
435	
436				detail := extractToolDetail(block.Name, input)
437	
438				entries = append(entries, Entry{
439					Type:       EntryTypeTool,
440					ToolName:   block.Name,
441					ToolDetail: detail,
442				})
443			}
444		}
445	
446		return entries
447	}
448	
449	// extractToolDetail extracts an appropriate detail string for a tool call.
450	// For tools in minimalDetailTools, only essential identifiers are shown.
451	// For other tools, the full detail chain is used.
452	func extractToolDetail(toolName string, input transcript.ToolInput) string {
453		// For minimal detail tools, extract only the essential identifier
454		if minimalDetailTools[toolName] {
455			switch toolName {
456			case "Skill":
457				return input.Skill
458			case "Read":
459				if input.FilePath != "" {
460					return input.FilePath
461				}
462				return input.NotebookPath
463			case "WebFetch":
464				return input.URL
465			}
466		}
467	
468		// For other tools, use the full detail chain
469		if input.Description != "" {
470			return input.Description
471		}
472		if input.Command != "" {
473			return input.Command
474		}
475		if input.FilePath != "" {
476			return input.FilePath
477		}
478		if input.NotebookPath != "" {
479			return input.NotebookPath
480		}
481		return input.Pattern
482	}
483	
484	// FormatCondensedTranscript formats an Input into a human-readable string for LLM.
485	// The format is:
486	//
487	//	[User] user prompt here
488	//
489	//	[Assistant] assistant response here
490	//
491	//	[Tool] ToolName: description or file path
492	func FormatCondensedTranscript(input Input) string {
493		var sb strings.Builder
494	
495		for i, entry := range input.Transcript {
496			if i > 0 {
497				sb.WriteString("\n")
498			}
499	
500			switch entry.Type {
501			case EntryTypeUser:
502				sb.WriteString("[User] ")
503				sb.WriteString(entry.Content)
504				sb.WriteString("\n")
505			case EntryTypeAssistant:
506				sb.WriteString("[Assistant] ")
507				sb.WriteString(entry.Content)
508				sb.WriteString("\n")
509			case EntryTypeTool:
510				sb.WriteString("[Tool] ")
511				sb.WriteString(entry.ToolName)
512				if entry.ToolDetail != "" {
513					sb.WriteString(": ")
514					sb.WriteString(entry.ToolDetail)
515				}
516				sb.WriteString("\n")
517			}
518		}
519	
520		if len(input.FilesTouched) > 0 {
521			sb.WriteString("\n[Files Modified]\n")
522			for _, file := range input.FilesTouched {
523				fmt.Fprintf(&sb, "- %s\n", file)
524			}
525		}
526	
527		return sb.String()
528	}
