package claudecode

import (
	"encoding/json"
	"errors"
	"fmt"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent"
)

type responseEnvelope struct {
	Type           string  `json:"type"`
	Subtype        string  `json:"subtype"`
	IsError        bool    `json:"is_error"`
	APIErrorStatus *int    `json:"api_error_status"`
	Result         *string `json:"result"`
}

// parseGenerateTextResponse extracts text + envelope metadata from the
// non-streaming Claude CLI JSON output, which may be a single object or an
// array. is_error:true envelopes with null result still return the envelope so
// classifyClaudeEnvelope can read IsError / APIErrorStatus.
func parseGenerateTextResponse(stdout []byte) (string, *responseEnvelope, error) {
	var response responseEnvelope
	if err := json.Unmarshal(stdout, &response); err == nil {
		if response.Result != nil {
			return *response.Result, &response, nil
		}
		if response.IsError {
			return "", &response, nil
		}
	}

	var responses []responseEnvelope
	if err := json.Unmarshal(stdout, &responses); err != nil {
		return "", nil, fmt.Errorf("unsupported Claude CLI JSON response: %w", err)
	}

	for i := len(responses) - 1; i >= 0; i-- {
		if responses[i].Type != "result" {
			continue
		}
		if responses[i].Result != nil {
			return *responses[i].Result, &responses[i], nil
		}
		if responses[i].IsError {
			return "", &responses[i], nil
		}
	}

	return "", nil, errors.New("unsupported Claude CLI JSON response: missing result item")
}

// streamEvent is one decoded NDJSON line from the Claude stream-json output.
// Fields populate based on Type/Subtype.
type streamEvent struct {
	Type    string           `json:"type"`
	Subtype string           `json:"subtype"`
	Status  string           `json:"status"`
	Event   streamInnerEvent `json:"event"`

	IsError        bool          `json:"is_error"`
	APIErrorStatus *int          `json:"api_error_status"`
	Result         *string       `json:"result"`
	DurationMs     int           `json:"duration_ms"`
	TTFTms         int           `json:"ttft_ms,omitempty"`
	Usage          *messageUsage `json:"usage"`
}

type streamInnerEvent struct {
	Type    string         `json:"type"`
	Delta   *streamDelta   `json:"delta,omitempty"`
	Message *streamMessage `json:"message,omitempty"`
}

type streamDelta struct {
	Type     string `json:"type"`
	Text     string `json:"text,omitempty"`
	Thinking string `json:"thinking,omitempty"`
}

type streamMessage struct {
	Usage *messageUsage `json:"usage,omitempty"`
}

// anthropicStreamHandler maps one NDJSON line from Claude stream-json output to
// StreamLineHandler output. Malformed lines are skipped (return nil,nil,nil)
// so a single bad line can't kill the whole stream.
func anthropicStreamHandler(line []byte, state *agent.StreamState) ([]agent.GenerationProgress, *agent.StreamResult, error) {
	var ev streamEvent
	if err := json.Unmarshal(line, &ev); err != nil {
		return nil, nil, nil
	}

	switch {
	case ev.Type == "system" && ev.Subtype == "status" && ev.Status == "requesting":
		return []agent.GenerationProgress{{Phase: agent.PhaseConnecting}}, nil, nil

	case ev.Type == "stream_event" && ev.Event.Type == "message_start":
		p := agent.GenerationProgress{Phase: agent.PhaseFirstToken, TTFTms: ev.TTFTms}
		if ev.Event.Message != nil && ev.Event.Message.Usage != nil {
			p.InputTokens = ev.Event.Message.Usage.InputTokens
			p.CachedInputTokens = ev.Event.Message.Usage.CacheReadInputTokens
		}
		return []agent.GenerationProgress{p}, nil, nil

	case ev.Type == "stream_event" && ev.Event.Type == "content_block_delta" && ev.Event.Delta != nil:
		text := ev.Event.Delta.Text
		if text == "" {
			text = ev.Event.Delta.Thinking
		}
		state.OutputTokensEstimate += len(text) / 4
		return []agent.GenerationProgress{{Phase: agent.PhaseGenerating, OutputTokens: state.OutputTokensEstimate}}, nil, nil

	case ev.Type == "result" && ev.IsError:
		result := ""
		if ev.Result != nil {
			result = *ev.Result
		}
		return nil, &agent.StreamResult{Err: classifyClaudeEnvelope(result, ev.APIErrorStatus, 0)}, nil

	case ev.Type == "result":
		if ev.Result == nil {
			return nil, &agent.StreamResult{Err: errors.New("claude returned empty result")}, nil
		}
		return nil, &agent.StreamResult{
			Text:         *ev.Result,
			OutputTokens: outputTokensFromUsage(ev.Usage),
			DurationMs:   ev.DurationMs,
		}, nil
	}
	return nil, nil, nil
}

func outputTokensFromUsage(u *messageUsage) int {
	if u == nil {
		return 0
	}
	return u.OutputTokens
}

const stderrMessageMaxLen = 500

// authStderrPhrases is intentionally small — the primary auth path is the
// structured envelope. These are a fallback for crashes that exit non-zero
// before the envelope is produced.
var authStderrPhrases = []string{
	"invalid api key",
	"not logged in",
}

// classifyClaudeEnvelope builds an *agent.Error from a Claude is_error envelope.
// Shared by the blocking (parseGenerateTextResponse) and streaming paths.
func classifyClaudeEnvelope(result string, apiStatus *int, exitCode int) *agent.Error {
	e := &agent.Error{
		Provider: "Anthropic",
		Message:  result,
		ExitCode: exitCode,
	}
	if apiStatus != nil {
		e.APIStatus = *apiStatus
	}
	switch {
	case e.APIStatus == 401, e.APIStatus == 403:
		e.Kind = agent.ErrorAuth
	case e.APIStatus == 429:
		e.Kind = agent.ErrorRateLimit
	case e.APIStatus >= 400 && e.APIStatus < 500:
		e.Kind = agent.ErrorConfig
	case e.APIStatus == 0 && hasAuthPhrase(result):
		e.Kind = agent.ErrorAuth
	default:
		e.Kind = agent.ErrorUnknown
	}
	return e
}

// classifyClaudeStderr is a fallback for non-zero exits without a parseable
// envelope. It only recognizes a small set of auth phrases.
func classifyClaudeStderr(stderr string, exitCode int) *agent.Error {
	msg := strings.TrimSpace(stderr)
	if len(msg) > stderrMessageMaxLen {
		msg = msg[:stderrMessageMaxLen]
	}
	e := &agent.Error{Provider: "Anthropic", Message: msg, ExitCode: exitCode}
	if hasAuthPhrase(msg) {
		e.Kind = agent.ErrorAuth
	} else {
		e.Kind = agent.ErrorUnknown
	}
	return e
}

func hasAuthPhrase(s string) bool {
	lower := strings.ToLower(s)
	for _, phrase := range authStderrPhrases {
		if strings.Contains(lower, phrase) {
			return true
		}
	}
	return false
}

package claudecode

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent"
)

// GenerateText runs Claude CLI in blocking JSON mode. Claude returns most
// operational errors as exit 0 with is_error:true on stdout, so we need
// structured access to stdout + stderr + exit code to produce typed
// *agent.Error values (which formatCheckpointSummaryError maps to actionable
// messages). That's why this bypasses agent.RunIsolatedTextGeneratorCLI.
func (c *ClaudeCodeAgent) GenerateText(ctx context.Context, prompt string, model string) (string, error) {
	if model == "" {
		model = "haiku"
	}

	runner := c.CommandRunner
	if runner == nil {
		runner = exec.CommandContext
	}

	cmd := runner(ctx, "claude",
		"--print", "--output-format", "json",
		"--model", model, "--setting-sources", "")
	cmd.Dir = os.TempDir()
	cmd.Env = agent.StripGitEnv(os.Environ())
	cmd.Stdin = strings.NewReader(prompt)

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	if err := cmd.Run(); err != nil {
		// Prefer a structured envelope over bare ctx sentinels: if the CLI
		// already emitted is_error on stdout, surface that even if ctx is done.
		if _, env, parseErr := parseGenerateTextResponse(stdout.Bytes()); parseErr == nil && env != nil && env.IsError {
			result := ""
			if env.Result != nil {
				result = *env.Result
			}
			exitCode := 0
			var exitErr *exec.ExitError
			if errors.As(err, &exitErr) {
				exitCode = exitErr.ExitCode()
			}
			return "", classifyClaudeEnvelope(result, env.APIErrorStatus, exitCode)
		}
		if errors.Is(ctx.Err(), context.DeadlineExceeded) {
			return "", context.DeadlineExceeded
		}
		if errors.Is(ctx.Err(), context.Canceled) {
			return "", context.Canceled
		}
		if isExecNotFound(err) {
			return "", &agent.Error{Kind: agent.ErrorCLIMissing, Provider: "Anthropic", Cause: err}
		}
		exitCode := -1
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) {
			exitCode = exitErr.ExitCode()
		}
		return "", classifyClaudeStderr(stderr.String(), exitCode)
	}

	result, env, err := parseGenerateTextResponse(stdout.Bytes())
	if err != nil {
		return "", &agent.Error{Kind: agent.ErrorUnknown, Provider: "Anthropic", Message: fmt.Sprintf("failed to parse claude CLI response: %v", err), Cause: err}
	}
	if env != nil && env.IsError {
		return "", classifyClaudeEnvelope(result, env.APIErrorStatus, 0)
	}

	return result, nil
}

// GenerateTextStreaming runs Claude CLI in stream-json mode via the shared
// RunStreamingCLI runtime. Falls back to the non-streaming path if the CLI
// rejects streaming flags (older CLIs).
func (c *ClaudeCodeAgent) GenerateTextStreaming(
	ctx context.Context, prompt, model string, progress agent.ProgressFn,
) (string, error) {
	if model == "" {
		model = "haiku"
	}
	return agent.RunStreamingCLI(ctx, agent.StreamConfig{
		Runner:        c.CommandRunner,
		Binary:        "claude",
		DisplayName:   "Claude",
		ProviderLabel: "Anthropic",
		Args: []string{
			"--print", "--output-format", "stream-json", "--verbose",
			"--model", model, "--setting-sources", "",
		},
		Stdin: prompt,
		LegacyFallback: func(ctx context.Context) (string, error) {
			return c.GenerateText(ctx, prompt, model)
		},
		FallbackDetect: looksLikeUnrecognizedFlag,
	}, anthropicStreamHandler, progress)
}

// looksLikeUnrecognizedFlag reports whether stderr indicates the CLI rejected
// a streaming-specific flag. Requires both a rejection phrase AND a known flag
// name to avoid false-positives on unrelated errors.
func looksLikeUnrecognizedFlag(stderr string) bool {
	lower := strings.ToLower(stderr)
	hasRejectPhrase := strings.Contains(lower, "unrecognized option") ||
		strings.Contains(lower, "unknown flag") ||
		strings.Contains(lower, "unknown option") ||
		strings.Contains(lower, "invalid option")
	if !hasRejectPhrase {
		return false
	}
	return strings.Contains(lower, "stream-json") ||
		strings.Contains(lower, "verbose") ||
		strings.Contains(lower, "include-partial")
}

// isExecNotFound returns true only when err indicates the binary was not
// found. Other *exec.Error causes (permission denied, bad executable format)
// surface as generic failures — those aren't fixed by reinstalling.
func isExecNotFound(err error) bool {
	var execErr *exec.Error
	if errors.As(err, &execErr) && errors.Is(execErr.Err, exec.ErrNotFound) {
		return true
	}
	return errors.Is(err, exec.ErrNotFound) || errors.Is(err, os.ErrNotExist)
}

