// replayHandler runs anthropicStreamHandler over an NDJSON body and returns
// the collected events + the terminal StreamResult. Shared across handler tests.
func replayHandler(t *testing.T, body []byte) ([]agent.GenerationProgress, *agent.StreamResult) {
	t.Helper()
	state := &agent.StreamState{}
	var events []agent.GenerationProgress
	var done *agent.StreamResult
	scanner := bufio.NewScanner(bytes.NewReader(body))
	scanner.Buffer(make([]byte, 0, 64*1024), 4*1024*1024)
	for scanner.Scan() {
		line := scanner.Bytes()
		if len(line) == 0 {
			continue
		}
		evs, terminal, err := anthropicStreamHandler(line, state)
		if err != nil {
			t.Fatalf("handler error = %v; want nil", err)
		}
		events = append(events, evs...)
		if terminal != nil {
			done = terminal
			break
		}
	}
	return events, done
}

