// to generate the summary" path. Prefers envelope Message, falls back to HTTP
// status, then exit code. ExitCode < 0 means the subprocess did not produce a
// real exit code (e.g. launch failure) — render as "abnormal termination".
func formatAgentErrorSuffix(e *agent.Error) string {
	if e.Message != "" {
		return ": " + e.Message
	}
	provider := e.Provider
	if provider == "" {
		provider = "provider"
	}
	switch {
