func (s *summaryProgressWriter) handle(p agent.GenerationProgress) {
	s.lastActivity.Store(time.Now().UnixNano())
	provider := p.ProviderLabel
	if provider == "" {
		provider = "provider"
	}
	switch p.Phase {
	case agent.PhaseConnecting:
		s.printLine(fmt.Sprintf("%s Sending request to %s...", s.arrow, provider))
	case agent.PhaseFirstToken:
		line := fmt.Sprintf("%s %s responded", s.arrow, provider)
		var detail []string
		if p.TTFTms > 0 {
			detail = append(detail, fmt.Sprintf("TTFT %s", formatMs(p.TTFTms)))
		}
		if p.CachedInputTokens > 0 {
			detail = append(detail, fmt.Sprintf("%s cached input tokens", formatTokenCount(p.CachedInputTokens)))
		}
		if len(detail) > 0 {
			line += " (" + strings.Join(detail, ", ") + ")"
		}
		s.printLine(line + " -- generating...")
	case agent.PhaseGenerating:
		if p.OutputTokens > 0 {
			s.updateLine(fmt.Sprintf("%s Writing summary... (~%s tokens)", s.arrow, formatTokenCount(p.OutputTokens)))
		} else {
			s.updateLine(fmt.Sprintf("%s Writing summary...", s.arrow))
		}
	case agent.PhaseMessage:
		if p.Message != "" {
			s.printLine(fmt.Sprintf("%s %s: %s", s.arrow, provider, p.Message))
		}
	case agent.PhaseDone:
		line := fmt.Sprintf("%s Summary generated", s.check)
		var detail []string
		if p.DurationMs > 0 {
			detail = append(detail, formatMs(p.DurationMs))
		}
		if p.OutputTokens > 0 {
			detail = append(detail, fmt.Sprintf("%s output tokens", formatTokenCount(p.OutputTokens)))
		}
		if len(detail) > 0 {
			line += " (" + strings.Join(detail, ", ") + ")"
		}
		s.printLine(line)
	}
}

