// ChooseGenerateTextPath picks streaming or blocking text generation based on
// what the text generator supports and whether the caller wants progress. When
// progress is non-nil and the generator implements StreamingTextGenerator, the
// streaming path wins — otherwise we fall back to the blocking GenerateText.
// Heartbeat mode is intentionally not wired here yet: every agent that calls
// this helper either already streams or is on track to in Phase 6.
func ChooseGenerateTextPath(
	ctx context.Context, tg agent.TextGenerator, prompt, model string, progress agent.ProgressFn,
) (string, error) {
	if progress != nil {
		if streamer, ok := agent.AsStreamingTextGenerator(tg); ok {
			return streamer.GenerateTextStreaming(ctx, prompt, model, progress)
		}
	}
	return tg.GenerateText(ctx, prompt, model)
}

